import{_ as o,o as a,c as t,a2 as s}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"为 Open Cube OS 做贡献","description":"","frontmatter":{},"headers":[],"relativePath":"zh/root/CONTRIBUTING.md","filePath":"zh/root/CONTRIBUTING.md"}'),d={name:"zh/root/CONTRIBUTING.md"};function i(c,e,l,n,r,p){return a(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="为-open-cube-os-做贡献" tabindex="-1">为 Open Cube OS 做贡献 <a class="header-anchor" href="#为-open-cube-os-做贡献" aria-label="Permalink to &quot;为 Open Cube OS 做贡献&quot;">​</a></h1><p>感谢你有意贡献！Open Cube OS 是一个从零写起的 x86_64 内核， 每一类贡献——代码、文档、驱动上线、bug 报告——都受欢迎。</p><h2 id="基本规则" tabindex="-1">基本规则 <a class="header-anchor" href="#基本规则" aria-label="Permalink to &quot;基本规则&quot;">​</a></h2><ol><li><p><strong>内核字符串是 ASCII 英文。</strong> 系统自身打印的一切（命令 名、提示符、启动消息、帮助文本）必须保持纯 ASCII。非 ASCII 文本可以出现在用户数据和文档里，绝不进入内核可见 的字符串。</p></li><li><p><strong>命令面只增不减。</strong> 已发布的 shell 命令可以在内部重做， 但其名字与总体行为必须保留；移除会破坏接口契约。用 <code>shell_register_command_ex()</code> 和一个工作包标签注册新命令。</p></li><li><p><strong>零警告。</strong> 构建以 <code>-Wall -Wextra -Werror</code> 编译。引入 警告的变更就是坏变更——在你的机器上是，在 CI 上也是。</p></li><li><p><strong>不要桩，不要假数据。</strong> 若特性不完整，在代码和文档里 明说——绝不掩饰。一个只做探测并报告&quot;此机不支持&quot;的驱动 没问题；一个假装能工作的驱动不行。</p></li><li><p><strong>处处 Apache 2.0。</strong> 每个新源文件以 SPDX 头开始：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/* SPDX-License-Identifier: Apache-2.0 */</span></span>
<span class="line"><span>/* Copyright 2026 cubestudio-dev &lt;cubestudio@qq.com&gt; */</span></span></code></pre></div></li></ol><h2 id="开发流程" tabindex="-1">开发流程 <a class="header-anchor" href="#开发流程" aria-label="Permalink to &quot;开发流程&quot;">​</a></h2><h3 id="_1-把构建跑起来" tabindex="-1">1. 把构建跑起来 <a class="header-anchor" href="#_1-把构建跑起来" aria-label="Permalink to &quot;1. 把构建跑起来&quot;">​</a></h3><p>遵循 <a href="./BUILDING.html">BUILDING.md</a>。Linux 上的短版本：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./build.sh iso          # kernel + bootable ISO</span></span>
<span class="line"><span>make test               # host-side unit tests</span></span></code></pre></div><p>你需要 <code>gcc, nasm, grub-mkimage, xorriso, mtools, python3, zip</code> （<code>tools/build.sh</code> 会检查并告诉你确切缺哪些，或用 <code>--install</code> 安装它们）。</p><h3 id="_2-做你的修改" tabindex="-1">2. 做你的修改 <a class="header-anchor" href="#_2-做你的修改" aria-label="Permalink to &quot;2. 做你的修改&quot;">​</a></h3><ul><li>保持修改聚焦：每个拉取请求一个驱动、一个修复或一个文档 章节。</li><li>每个内核源文件都携带 SPDX 头——保留它。</li><li>新命令：在对应的 <code>shell/shell_cmds_*.c</code> 里注册、 添加帮助行，并扩展回归期望 （见 <code>tools/run_fix4_regression.py</code>，命令计数基线）。</li></ul><h3 id="_3-推送前测试" tabindex="-1">3. 推送前测试 <a class="header-anchor" href="#_3-推送前测试" aria-label="Permalink to &quot;3. 推送前测试&quot;">​</a></h3><p>最低门槛，全部要过：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make kernel             # 0 errors, 0 warnings (-Werror enforced)</span></span>
<span class="line"><span>make test               # host unit suite (tools/run_host_tests.py)</span></span>
<span class="line"><span>make iso                # hybrid BIOS+UEFI ISO builds</span></span>
<span class="line"><span>make reproducible-check # two clean builds -&gt; byte-identical ELF</span></span></code></pre></div><p>然后启动它：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make run-bios   # or: qemu-system-x86_64 -cdrom build/opencube.iso</span></span>
<span class="line"><span>make run-uefi   # OVMF path</span></span></code></pre></div><p>若你的修改碰到下表所列内容，对应的深度测试同样必须跑：</p><table tabindex="0"><thead><tr><th>你碰了…</th><th>还要跑</th></tr></thead><tbody><tr><td>存储 / 文件系统</td><td>客户机里的 <code>fstest</code>、<code>dhtest</code></td></tr><tr><td>加密 / TLS / SSH</td><td>客户机里的 <code>cryptotest</code>、HTTPS E2E</td></tr><tr><td>看门狗 / klog / health</td><td><code>tools/wp12_watchdog_logging_e2e.py build/opencube.iso</code></td></tr><tr><td>完整启动路径</td><td>回归套件（<code>tools/run_fix4_regression.py</code>）</td></tr><tr><td>A/B 槽位或 OTA</td><td>客户机里的 <code>ab_partition_test</code>、OTA 安装测试</td></tr></tbody></table><p>CI（<code>.github/workflows/build.yml</code>）在每个 PR 上运行构建、 打包、宿主机测试和可复现性门禁——合并前必须绿。</p><h3 id="_4-提交风格" tabindex="-1">4. 提交风格 <a class="header-anchor" href="#_4-提交风格" aria-label="Permalink to &quot;4. 提交风格&quot;">​</a></h3><ul><li>每个逻辑步骤一个提交；每条提交信息回答<em>什么</em>和 <em>为什么</em>，而不只是<em>什么</em>。</li><li>用领域作前缀：<code>usb: ...</code>、<code>fs: fat32: ...</code>、<code>docs: ...</code>、 <code>build: ...</code>。</li><li>若你修复了一个被跟踪的审计 bug，在信息里引用它的 编号（<code>BUG-0136</code>）。</li></ul><h3 id="_5-拉取请求" tabindex="-1">5. 拉取请求 <a class="header-anchor" href="#_5-拉取请求" aria-label="Permalink to &quot;5. 拉取请求&quot;">​</a></h3><ol><li>从 <code>main</code> 分叉或开分支。</li><li>推送你的分支，向 <code>cubestudio-dev/OpenCubeOS</code> 开 PR。</li><li>填写 PR 模板的核对清单： <ul><li>[ ] 以 0 警告构建（<code>-Wall -Wextra -Werror</code>）</li><li>[ ] 宿主机测试通过（<code>make test</code>）</li><li>[ ] 在 QEMU 里启动过（BIOS 与 UEFI）</li><li>[ ] 相关深度测试通过（上表）</li><li>[ ] 文档已更新（<code>docs/</code> 下的手册页，L1 面变更时还有 接口清单）</li></ul></li><li>预期会收到关于边界情形、DMA 界限和错误路径的评审 意见——对内核代码来说这很正常。</li></ol><h2 id="版本号纪律-3-0-0-阶段" tabindex="-1">版本号纪律（3.0.0 阶段） <a class="header-anchor" href="#版本号纪律-3-0-0-阶段" aria-label="Permalink to &quot;版本号纪律（3.0.0 阶段）&quot;">​</a></h2><p><strong>一个阶段，一个版本主干。</strong> 在 3.0.0 阶段的 74 个工作包走完之前， 发布版本号固定为 <code>3.0.0-WP-&lt;工作包名&gt;</code>。minor 与 patch 号<strong>不得</strong> 自行变动：任何贡献者、任何单个工作包都不得在本阶段抬升 patch 号、 minor 号或 major 号——主干始终是 <code>3.0.0</code>。工作包只把自己写进后缀， 绝不抬升主干。</p><p><strong><code>Makefile</code> 里的字面量是唯一真源。</strong> <code>Makefile</code>（<code>Makefile:102</code>）中的 <code>OC_RELEASE_VERSION</code> 是版本串的唯一权威——内核横幅、<code>uname</code>、OTA 清单 与 ISO 全部取自它。改动这个字面量属于<strong>发布动作</strong>而非代码改动：必须 由工作包授权，并且会牵动整棵代码树。</p><p><strong>版本串分布在多处，改动必须全覆盖。</strong> 同一串版本号出现在 <code>Makefile</code>、 <code>README.md</code>、<code>docs/release/</code>、<code>website/</code> 静态页与 <code>website/assets/site-data.js</code>、<code>update.json</code> / <code>update-v2.json</code> 清单、 git tag 名，以及资产文件名（<code>.iso</code>、<code>-src.zip</code>、<code>-update.tar.gz</code>）中。 只改一处从来不算版本变更——版本变更是全仓对账。验收是机械的： <code>git grep -n &#39;&lt;旧版本号&gt;&#39;</code> 必须查无残留，只允许有据可查的非版本号误命中 （上游 npm 包版本号、文档保留 IP、归档证据文件名）。</p><p><strong>违反即视为发布事故。</strong> 未经授权的版本号跃升按发布事故处理，而不是 笔误。回滚流程为：全仓替换版本串 → 重打 tag → 重传资产 → 重部署 gh-pages——按此顺序，每一步之间 <code>git grep</code> 检查必须为绿。</p><p>参考：<code>docs/release/versioning.md</code>（版本管理规则、构建号与兼容承诺）。</p><h3 id="提交与推送纪律" tabindex="-1">提交与推送纪律 <a class="header-anchor" href="#提交与推送纪律" aria-label="Permalink to &quot;提交与推送纪律&quot;">​</a></h3><p>这条适用于<strong>每一个</strong>任务，不只是发布任务。</p><p><strong>一次验证过的批量，一次推送。</strong> 只有批量内<em>全部</em>任务完成并验证通过后， 才提交并推送。禁止边做边推，禁止推送半成品：一次推送即声明代码树能构建、 能启动、且门禁全绿。</p><p><strong>提交前以下各项必须全部成立：</strong> <code>make all</code> 0 错误 0 警告、全量回归通过、 <code>git status</code> 无遗漏的生成物（版本戳、<code>docs/data/*.json</code>、生成的镜像文件）、 且没有仍在后台运行的构建或测试进程。</p><p><strong>双仓，一次推送。</strong> 公开仓 <code>cubestudio-dev/OpenCubeOS</code> 与私密镜像仓 <strong>同时</strong>推送——一次推送覆盖两者。只到达其中一个仓的提交属于不完整交付。</p><p><strong>Author 身份是机器硬门。</strong> git author 必须是 <code>cubestudio-dev &lt;cubestudio@qq.com&gt;</code>；<code>tools/build_release.sh</code>（<code>:44-45</code>） 以机械方式强制该身份，不符即构建失败。</p><p><strong>gh-pages 跟随推送。</strong> 只在推送落地后才部署 gh-pages，并线上验证—— 部署后的页面是交付的一部分，不是后续补充。</p><p>相关：<code>docs/dev/pr-workflow.md</code>（本批量纪律所依托的拉取请求门槛）。</p><h2 id="报告-bug" tabindex="-1">报告 bug <a class="header-anchor" href="#报告-bug" aria-label="Permalink to &quot;报告 bug&quot;">​</a></h2><p>开一个 issue，附上：</p><ul><li>客户机里 <code>uname -a</code> 的构建标识、</li><li>确切的命令序列、</li><li>串口日志（<code>-serial file:log.txt</code> 是你的朋友）、</li><li>在 BIOS、UEFI 还是两者上复现。</li></ul><p>安全敏感的报告：见 README 中的 <code>SECURITY</code> 注记——不要 开公开 issue；改为邮件联系维护者。</p><h2 id="文档贡献" tabindex="-1">文档贡献 <a class="header-anchor" href="#文档贡献" aria-label="Permalink to &quot;文档贡献&quot;">​</a></h2><p><code>docs/</code> 下的文档树是产品本身，不是事后补充。若你新增 一条命令或一个接口，对应的手册/参考页必须在同一个 PR 里 落地。参考页从真实代码树生成（<code>make api-docs</code>）——不要 手改生成的表。</p><h2 id="许可" tabindex="-1">许可 <a class="header-anchor" href="#许可" aria-label="Permalink to &quot;许可&quot;">​</a></h2><p>提交贡献即表示你同意它以 Apache 2.0 授权（仓库根的 <code>LICENSE</code> 文件），且版权行可以携带项目的持有者。</p><p>感谢你和我们一起构建 Open Cube OS。</p>`,46)])])}const g=o(d,[["render",i]]);export{u as __pageData,g as default};
